kernel vec4 filmResponse(__sample pixel, vec3 a0, vec3 a1, vec3 a2,
                         vec3 b0, vec3 b1, vec3 b2, vec3 slopes, float reference) {
    vec4 p = unpremultiply(pixel);
    vec3 exposed = max(vec3(dot(a0,p.rgb), dot(a1,p.rgb), dot(a2,p.rgb)), vec3(0.0));
    vec3 h = log2(max(exposed,vec3(1e-20)) / reference);
    vec3 base = vec3(1.0) / (vec3(1.0) + exp(-h * 0.5));
    vec3 layer = vec3(1.0) / (vec3(1.0) + exp(-h * slopes * 0.5));
    vec3 response = exposed * exp2(8.0 * (layer - base));
    vec3 returned = vec3(dot(b0,response), dot(b1,response), dot(b2,response));
    return premultiply(vec4(max(returned,vec3(0.0)),p.a));
}

kernel vec4 hdfAdd(__sample pixel, __sample blurred, float amount) {
    vec4 p = unpremultiply(pixel);
    vec3 glow = unpremultiply(blurred).rgb;
    return premultiply(vec4(max(p.rgb + amount * glow, vec3(0.0)), p.a));
}

kernel vec4 clarityAdjust(__sample pixel, __sample blurred, float amount, float ceiling) {
    vec4 p = unpremultiply(pixel);
    vec3 base = clamp(p.rgb / ceiling, 0.0, 1.0);
    vec3 low = unpremultiply(blurred).rgb / ceiling;
    vec3 highPass = clamp(vec3(0.5) + base - low, 0.0, 1.0);
    if (amount < 0.0) { highPass = 1.0 - highPass; }
    vec3 d = mix(((16.0 * base - 12.0) * base + 4.0) * base,
                 sqrt(base), step(vec3(0.25), base));
    vec3 darken = base - (1.0 - 2.0 * highPass) * base * (1.0 - base);
    vec3 lighten = base + (2.0 * highPass - 1.0) * (d - base);
    vec3 blended = mix(darken, lighten, step(vec3(0.5), highPass));
    vec3 result = clamp(mix(base, blended, clamp(abs(amount), 0.0, 2.0)), 0.0, 1.0);
    return premultiply(vec4(result * ceiling, p.a));
}

kernel vec4 toneMap(sampler source, sampler table, float black, float span,
                    float lastIndex) {
    vec4 pixel = unpremultiply(sample(source, samplerCoord(source)));
    vec3 t = (pixel.rgb - vec3(black)) / span;
    vec3 u = clamp(t, 0.0, 1.0) * lastIndex + vec3(0.5);
    vec3 mapped = vec3(
        sample(table, samplerTransform(table, vec2(u.r, 0.5))).r,
        sample(table, samplerTransform(table, vec2(u.g, 0.5))).g,
        sample(table, samplerTransform(table, vec2(u.b, 0.5))).b);
    return premultiply(vec4(mapped, pixel.a));
}

kernel vec4 toneLocator(__sample sourcePixel, __sample preview, vec3 weights,
                        float position, float width, float clipping) {
    vec3 rgb = unpremultiply(sourcePixel).rgb;
    float distance = abs(dot(rgb, weights) - position);
    float mask = 1.0 - smoothstep(width * 0.35, width, distance);
    if (clipping > 0.5) { mask = step(position, max(rgb.r, max(rgb.g, rgb.b))); }
    vec3 highlight = clipping > 0.5 ? vec3(1.0, 0.0, 0.0) : vec3(0.21404114);
    vec4 base = unpremultiply(preview);
    return premultiply(vec4(mix(base.rgb, highlight, mask * 0.9), base.a));
}

kernel vec4 inputOffset(__sample pixel, float offset) {
    // Equal linear-light addition. Bound negative RGB, retain HDR values.
    return vec4(max(pixel.rgb + vec3(offset * pixel.a), vec3(0.0)), pixel.a);
}

kernel vec4 gain(__sample base, __sample alternate, float rgb, vec3 weights) {
    vec3 s = max(unpremultiply(base).rgb, vec3(0.0));
    vec3 h = max(unpremultiply(alternate).rgb, vec3(0.0));
    if (rgb < 0.5) {
        s = vec3(dot(s, weights));
        h = vec3(dot(h, weights));
    }
    return vec4(log2((h + vec3(0.00001)) / (s + vec3(0.00001))), 1.0);
}

kernel vec4 monochrome(__sample pixel, vec3 weights, vec3 first, vec2 last) {
    vec4 p = unpremultiply(pixel);
    vec3 rgb = max(p.rgb, 0.0);
    rgb /= max(1.0, max(rgb.r, max(rgb.g, rgb.b)));
    float hi = max(rgb.r, max(rgb.g, rgb.b));
    float lo = min(rgb.r, min(rgb.g, rgb.b));
    float delta = hi - lo;
    float sensitivity = 1.0;
    if (delta > 0.000001) {
        float hue;
        if (hi == rgb.r) { hue = mod((rgb.g - rgb.b) / delta, 6.0); }
        else if (hi == rgb.g) { hue = (rgb.b - rgb.r) / delta + 2.0; }
        else { hue = (rgb.r - rgb.g) / delta + 4.0; }
        float magenta = (last.y + first.x) * 0.5;
        float a = first.x, b = first.y;
        if (hue >= 5.0) { a = magenta; b = first.x; }
        else if (hue >= 4.0) { a = last.y; b = magenta; }
        else if (hue >= 3.0) { a = last.x; b = last.y; }
        else if (hue >= 2.0) { a = first.z; b = last.x; }
        else if (hue >= 1.0) { a = first.y; b = first.z; }
        float t = fract(hue);
        // Relative chroma vanishes at neutral colors, including near-white RGB.
        // HSL saturation instead stays at one along an edge leading into white.
        float saturation = delta / max(0.000001, hi);
        sensitivity = mix(1.0, mix(a, b, t*t*(3.0-2.0*t)), clamp(saturation,0.0,1.0));
    }
    float gray = max(0.0, dot(p.rgb, weights) * sensitivity);
    return premultiply(vec4(vec3(gray),p.a));
}

kernel vec4 vignetteExposure(__sample pixel, vec4 extent, vec3 row0, vec3 row1,
                             vec3 row2, float aspect, float amount, float exponent) {
    vec2 source = (destCoord() - extent.xy) / extent.zw;
    vec3 position = vec3(source.x, 1.0 - source.y, 1.0);
    float denominator = dot(row2, position);
    float radius = 1.0;
    // A projective horizon can lie outside the retained crop. Bound its loss
    // to the corner amount so neighboring blur samples stay finite.
    if (abs(denominator) > 0.000001) {
        vec2 crop = vec2(dot(row0, position), dot(row1, position)) / denominator;
        vec2 centered = (2.0 * crop - 1.0) * vec2(aspect, 1.0);
        radius = clamp(length(centered) / sqrt(aspect * aspect + 1.0), 0.0, 1.0);
    }
    float gain = exp2(-amount * pow(radius, exponent));
    return vec4(pixel.rgb * gain, pixel.a);
}

kernel vec4 halationInput(__sample source, float exponent) {
    vec4 p = unpremultiply(source);
    vec3 positive = max(p.rgb, vec3(0.0));
    // Shape the unit interval; preserve above-white headroom without power amplification.
    vec3 shaped = pow(min(positive, vec3(1.0)), vec3(exponent))
        + max(positive - vec3(1.0), vec3(0.0));
    return premultiply(vec4(shaped, p.a));
}

kernel vec4 halationAdd(__sample source, __sample redHalo, __sample greenHalo, float strength, float transmission, float ceiling, float monochrome) {
    vec4 p = unpremultiply(source);
    if (monochrome > 0.5) {
        p.rgb = max(p.rgb + strength * unpremultiply(redHalo).rgb, vec3(0.0));
        if (ceiling > 0.0) { p.rgb = min(p.rgb, vec3(ceiling)); }
        return premultiply(p);
    }
    float red = unpremultiply(redHalo).r;
    float green = unpremultiply(greenHalo).g;
    p.r = max(p.r + strength * red, 0.0);
    p.g = max(p.g + strength * transmission * green, 0.0);
    if (ceiling > 0.0) { p.rg = min(p.rg, vec2(ceiling)); }
    return premultiply(p);
}

kernel vec4 profileLUT(sampler source, sampler cube, vec3 low, vec3 span, float dimension) {
    vec4 p = unpremultiply(sample(source,samplerCoord(source)));
    vec3 t = clamp((p.rgb-low)/span,0.0,1.0)*(dimension-1.0);
    vec3 a = floor(t), b = min(a+1.0,vec3(dimension-1.0)), f = t-a;
    vec3 c000 = sample(cube,samplerTransform(cube,vec2(a.x,a.y+a.z*dimension)+vec2(0.5))).rgb;
    vec3 c100 = sample(cube,samplerTransform(cube,vec2(b.x,a.y+a.z*dimension)+vec2(0.5))).rgb;
    vec3 c010 = sample(cube,samplerTransform(cube,vec2(a.x,b.y+a.z*dimension)+vec2(0.5))).rgb;
    vec3 c110 = sample(cube,samplerTransform(cube,vec2(b.x,b.y+a.z*dimension)+vec2(0.5))).rgb;
    vec3 c001 = sample(cube,samplerTransform(cube,vec2(a.x,a.y+b.z*dimension)+vec2(0.5))).rgb;
    vec3 c101 = sample(cube,samplerTransform(cube,vec2(b.x,a.y+b.z*dimension)+vec2(0.5))).rgb;
    vec3 c011 = sample(cube,samplerTransform(cube,vec2(a.x,b.y+b.z*dimension)+vec2(0.5))).rgb;
    vec3 c111 = sample(cube,samplerTransform(cube,vec2(b.x,b.y+b.z*dimension)+vec2(0.5))).rgb;
    vec3 c = mix(mix(mix(c000,c100,f.x),mix(c010,c110,f.x),f.y),
                 mix(mix(c001,c101,f.x),mix(c011,c111,f.x),f.y),f.z);
    return premultiply(vec4(c,p.a));
}

kernel vec4 lutDomain(__sample source, vec3 low, vec3 span) {
    vec4 p = unpremultiply(source);
    // Clamp HDR to SDR white before applying the LUT's declared domain.
    p.rgb = (clamp(p.rgb, 0.0, 1.0) - low) / span;
    return premultiply(p);
}

kernel vec4 lutHDRGain(__sample originalHDR, __sample originalSDR, __sample gradedSDR) {
    vec4 h = unpremultiply(originalHDR);
    vec3 s = clamp(unpremultiply(originalSDR).rgb, 0.0, 1.0);
    vec3 graded = max(unpremultiply(gradedSDR).rgb, vec3(0.0));
    // Match the linear-light offsets used by ISO gain-map generation.
    // Offset reconstruction is identity when the grade is identity,
    // and remains defined for black or zero-valued color channels.
    vec3 gain = (max(h.rgb, vec3(0.0)) + vec3(0.00001)) / (s + vec3(0.00001));
    vec3 result = max((graded + vec3(0.00001)) * gain - vec3(0.00001), vec3(0.0));
    return premultiply(vec4(result, h.a));
}

kernel vec4 badHDR(__sample original, __sample blurred, float strength, float white, vec3 weights) {
    vec4 p = unpremultiply(original);
    // The SDR-range blurred copy becomes a multiplier from 1 to 0.5.
    // Clamp the mask so HDR highlights cannot invert or darken to black.
    float mask = clamp(dot(unpremultiply(blurred).rgb, weights) / white, 0.0, 1.0);
    // One exposure multiplier preserves RGB ratios. Negative strength
    // applies its reciprocal.
    float multiplier = pow(1.0 - 0.5 * mask, strength);
    return premultiply(vec4(p.rgb * multiplier, p.a));
}

// Björn Ottosson's OKLab transform; RGB is linear sRGB, D65.
vec3 toOKLab(vec3 c) {
    vec3 lms = vec3(dot(c, vec3(0.4122214708,0.5363325363,0.0514459929)),
                    dot(c, vec3(0.2119034982,0.6806995451,0.1073969566)),
                    dot(c, vec3(0.0883024619,0.2817188376,0.6299787005)));
    lms = sign(lms) * pow(abs(lms), vec3(1.0/3.0));
    return vec3(dot(lms,vec3(0.2104542553,0.7936177850,-0.0040720468)),
                dot(lms,vec3(1.9779984951,-2.4285922050,0.4505937099)),
                dot(lms,vec3(0.0259040371,0.7827717662,-0.8086757660)));
}
vec3 fromOKLab(vec3 c) {
    vec3 lms = vec3(c.x+0.3963377774*c.y+0.2158037573*c.z,
                    c.x-0.1055613458*c.y-0.0638541728*c.z,
                    c.x-0.0894841775*c.y-1.2914855480*c.z);
    lms = lms*lms*lms;
    return vec3(dot(lms,vec3(4.0767416621,-3.3077115913,0.2309699292)),
                dot(lms,vec3(-1.2684380046,2.6097574011,-0.3413193965)),
                dot(lms,vec3(-0.0041960863,-0.7034186147,1.7076147010)));
}
vec3 convertRGB(vec3 c, vec3 row0, vec3 row1, vec3 row2) {
    return vec3(dot(row0,c),dot(row1,c),dot(row2,c));
}
float chromaMultiplier(float x, vec4 points, float hdrEnd) {
    if (x <= 0.5) { return mix(points.x,points.y,clamp(x*2.0,0.0,1.0)); }
    if (x <= 1.0) { return mix(points.y,points.z,(x-0.5)*2.0); }
    if (hdrEnd <= 1.000001) { return points.z; }
    return mix(points.z,points.w,clamp((x-1.0)/(hdrEnd-1.0),0.0,1.0));
}

    float sliceBend(float L,float C,vec4 bend,float apex) {
        float endpoint=L<apex ? bend.x:bend.y;
        float t=clamp(abs(L-apex)/max(0.000001,abs(endpoint-apex)),0.0,1.0);
        float c=clamp(C/0.1,0.0,1.0);
        return (L<apex ? bend.z:bend.w)*t*t*(3.0-2.0*t)*c*c*(3.0-2.0*c);
    }
    kernel vec4 combinedOKLab(sampler image,sampler tintTable,
        float ceiling,float domain,float maximumChroma,vec4 chroma,vec4 lightness,
        float hasTint,float hasWarp,
        vec3 to0,vec3 to1,vec3 to2,vec3 from0,vec3 from1,vec3 from2,
        vec4 v0,vec2 h0,vec4 b0,float l0,vec4 v1,vec2 h1,vec4 b1,float l1,vec4 v2,vec2 h2,vec4 b2,float l2,vec4 v3,vec2 h3,vec4 b3,float l3,vec4 v4,vec2 h4,vec4 b4,float l4,vec4 v5,vec2 h5,vec4 b5,float l5,vec4 v6,vec2 h6,vec4 b6,float l6) {
        vec4 pixel=unpremultiply(sample(image,samplerCoord(image)));
        vec3 lab=toOKLab(convertRGB(pixel.rgb,to0,to1,to2));
        float multiplier=chromaMultiplier(length(lab.yz)/maximumChroma,chroma,domain)
            * chromaMultiplier(lab.x,lightness,domain);
        lab.yz *= max(0.0,multiplier);
        if (hasWarp > 0.5) {
            float scale=pow(ceiling,1.0/3.0);
            vec3 q=lab/scale;
            float c=length(q.yz);
            vec3 warped=q;
            if (c>0.0000000001) {
                float h=atan(q.z,q.y);
                if (h<h0.x) { h+=6.28318530718; }
                vec3 adjustment=vec3(1.0,0.0,0.0);

        if (h>=h0.x && h<=h0.y) {
            float t=(h-h0.x)/(h0.y-h0.x);
            float w=t*t*(3.0-2.0*t);
            adjustment=mix(v0.xyz,v1.xyz,w);
            adjustment.z += mix(sliceBend(q.x,c,b0,l0),sliceBend(q.x,c,b1,l1),w);
            float r0=clamp(c/v0.w,0.0,1.0),r1=clamp(c/v1.w,0.0,1.0);
            adjustment.y=mix(v0.y*r0*r0*(3.0-2.0*r0),v1.y*r1*r1*(3.0-2.0*r1),w);
        }


        if (h>=h1.x && h<=h1.y) {
            float t=(h-h1.x)/(h1.y-h1.x);
            float w=t*t*(3.0-2.0*t);
            adjustment=mix(v1.xyz,v2.xyz,w);
            adjustment.z += mix(sliceBend(q.x,c,b1,l1),sliceBend(q.x,c,b2,l2),w);
            float r0=clamp(c/v1.w,0.0,1.0),r1=clamp(c/v2.w,0.0,1.0);
            adjustment.y=mix(v1.y*r0*r0*(3.0-2.0*r0),v2.y*r1*r1*(3.0-2.0*r1),w);
        }


        if (h>=h2.x && h<=h2.y) {
            float t=(h-h2.x)/(h2.y-h2.x);
            float w=t*t*(3.0-2.0*t);
            adjustment=mix(v2.xyz,v3.xyz,w);
            adjustment.z += mix(sliceBend(q.x,c,b2,l2),sliceBend(q.x,c,b3,l3),w);
            float r0=clamp(c/v2.w,0.0,1.0),r1=clamp(c/v3.w,0.0,1.0);
            adjustment.y=mix(v2.y*r0*r0*(3.0-2.0*r0),v3.y*r1*r1*(3.0-2.0*r1),w);
        }


        if (h>=h3.x && h<=h3.y) {
            float t=(h-h3.x)/(h3.y-h3.x);
            float w=t*t*(3.0-2.0*t);
            adjustment=mix(v3.xyz,v4.xyz,w);
            adjustment.z += mix(sliceBend(q.x,c,b3,l3),sliceBend(q.x,c,b4,l4),w);
            float r0=clamp(c/v3.w,0.0,1.0),r1=clamp(c/v4.w,0.0,1.0);
            adjustment.y=mix(v3.y*r0*r0*(3.0-2.0*r0),v4.y*r1*r1*(3.0-2.0*r1),w);
        }


        if (h>=h4.x && h<=h4.y) {
            float t=(h-h4.x)/(h4.y-h4.x);
            float w=t*t*(3.0-2.0*t);
            adjustment=mix(v4.xyz,v5.xyz,w);
            adjustment.z += mix(sliceBend(q.x,c,b4,l4),sliceBend(q.x,c,b5,l5),w);
            float r0=clamp(c/v4.w,0.0,1.0),r1=clamp(c/v5.w,0.0,1.0);
            adjustment.y=mix(v4.y*r0*r0*(3.0-2.0*r0),v5.y*r1*r1*(3.0-2.0*r1),w);
        }


        if (h>=h5.x && h<=h5.y) {
            float t=(h-h5.x)/(h5.y-h5.x);
            float w=t*t*(3.0-2.0*t);
            adjustment=mix(v5.xyz,v6.xyz,w);
            adjustment.z += mix(sliceBend(q.x,c,b5,l5),sliceBend(q.x,c,b6,l6),w);
            float r0=clamp(c/v5.w,0.0,1.0),r1=clamp(c/v6.w,0.0,1.0);
            adjustment.y=mix(v5.y*r0*r0*(3.0-2.0*r0),v6.y*r1*r1*(3.0-2.0*r1),w);
        }


        if (h>=h6.x && h<=h6.y) {
            float t=(h-h6.x)/(h6.y-h6.x);
            float w=t*t*(3.0-2.0*t);
            adjustment=mix(v6.xyz,v0.xyz,w);
            adjustment.z += mix(sliceBend(q.x,c,b6,l6),sliceBend(q.x,c,b0,l0),w);
            float r0=clamp(c/v6.w,0.0,1.0),r1=clamp(c/v0.w,0.0,1.0);
            adjustment.y=mix(v6.y*r0*r0*(3.0-2.0*r0),v0.y*r1*r1*(3.0-2.0*r1),w);
        }

                warped=vec3(q.x+adjustment.y,c*adjustment.x*cos(h+adjustment.z),c*adjustment.x*sin(h+adjustment.z));
            }
            lab=warped*scale;
        }
        if (hasTint > 0.5) {
            lab.yz += sample(tintTable,vec2(clamp(lab.x/domain,0.0,1.0)*511.0+0.5,0.5)).xy;
        }
        // Gamut handling is deferred until every OKLab operation is complete.
        // Fit along a straight line toward neutral in linear working RGB.
        // The RGB cube is convex, unlike fixed-L OKLab chroma slices near
        // deep blue: this intersection is unique and continuous, with no
        // branch-search jumps. In-gamut colors remain unchanged. Out-of-gamut
        // colors may change perceptual lightness/hue slightly while fitting.
        vec3 rgb=convertRGB(fromOKLab(lab),from0,from1,from2);
        float gray=clamp(lab.x*lab.x*lab.x,0.0,ceiling);
        vec3 delta=rgb-vec3(gray);
        float fit=1.0;
        float lowest=min(rgb.r,min(rgb.g,rgb.b));
        float highest=max(rgb.r,max(rgb.g,rgb.b));
        if (lowest<0.0) { fit=min(fit,gray/(gray-lowest)); }
        if (highest>ceiling) { fit=min(fit,(ceiling-gray)/(highest-gray)); }
        rgb=clamp(vec3(gray)+delta*fit,0.0,ceiling);
        return premultiply(vec4(rgb,pixel.a));
    }
